def sort_by_year_then_title(records):
    from functools import cmp_to_key
    def compare(a, b):
        if a[1] != b[1]:
            return -1 if a[1] < b[1] else 1
        if a[0] != b[0]:
            return -1 if a[0] < b[0] else 1
        return 0
    return sorted(records, key=cmp_to_key(compare))

