def longest_decreasing_run(lst):
    if not lst:
        return 0
    run_lengths = [1]
    for i in range(1, len(lst)):
        if lst[i] < lst[i - 1]:
            run_lengths.append(run_lengths[-1] + 1)
        else:
            run_lengths.append(1)
    return max(run_lengths)

def wrap_count_lines(text, width):
    words = text.split()
    if not words:
        return 0
    lines = [words[0]]
    for word in words[1:]:
        if len(lines[-1]) + 1 + len(word) <= width:
            lines[-1] = lines[-1] + ' ' + word
        else:
            lines.append(word)
    return len(lines)

