def add_days_to_date_string_dmy(date_str, n):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def days_in_month(y, m):
        lengths = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return lengths[m - 1]

    d, m, y = (int(p) for p in date_str.split('-'))
    step = 1 if n >= 0 else -1
    remaining = abs(n)
    while remaining > 0:
        d += step
        if step == 1 and d > days_in_month(y, m):
            d = 1
            m += 1
            if m > 12:
                m = 1
                y += 1
        elif step == -1 and d < 1:
            m -= 1
            if m < 1:
                m = 12
                y -= 1
            d = days_in_month(y, m)
        remaining -= 1
    return f'{d:02d}-{m:02d}-{y:04d}'

