def zigzag_merge(lst):
    s = sorted(lst)
    def helper(seq, take_low):
        if not seq:
            return []
        if take_low:
            return [seq[0]] + helper(seq[1:], False)
        else:
            return [seq[-1]] + helper(seq[:-1], True)
    return helper(s, True)

from collections import defaultdict

def shared_key_sum(dicts_list):
    values_by_key = defaultdict(list)
    for d in dicts_list:
        for key, value in d.items():
            values_by_key[key].append(value)
    return {key: sum(vals) for key, vals in values_by_key.items() if len(vals) >= 2}

def local_extrema_count(lst):
    n = len(lst)
    if n < 3:
        return 0
    total = 0
    triples = zip(lst, lst[1:], lst[2:])
    for a, b, c in triples:
        if (b > a and b > c) or (b < a and b < c):
            total += 1
    return total

