def is_valid_simple_url(s):
    if ' ' in s:
        return False
    for scheme in ('https://', 'http://'):
        if s.startswith(scheme):
            remainder = s[len(scheme):]
            break
    else:
        return False
    if not remainder:
        return False
    domain, _, path = remainder.partition('/')
    if not domain:
        return False
    parts = domain.split('.')
    if len(parts) < 2:
        return False
    def valid_label(lbl):
        if not lbl or lbl[0] == '-' or lbl[-1] == '-':
            return False
        return all(ch.isalnum() or ch == '-' for ch in lbl)
    if not all(valid_label(p) for p in parts):
        return False
    tld = parts[-1]
    return tld.isalpha() and len(tld) >= 2

